    const h = gated(1, store);
    const run = h.send(userMessage('A'));
    await afterPendingWork();

    await h.send({type: 'list_sessions'});
    const whileHeld = h.frames();
    h.release(0);
    await run;

    expect({asked, whileHeld, frames: h.frames()}).toEqual({
      asked: ['u1'],
      whileHeld: ['upsert 0 user "A"', 'upsert 1 assistant ""', 'delta 1 "answer 0"', 'session_list'],
      frames: [
        'upsert 0 user "A"',
        'upsert 1 assistant ""',
        'delta 1 "answer 0"',
        'session_list',
        'commit 1',
        'stream_end',
      ],
    });
  });

  it('answers off-lock frames in arrival order: a list_sessions is not overtaken by the pong of a ping sent after it', async () => {
    const store = {
      listFor: () => [
        {
          sessionId: 's9',
          createdAt: new Date('2026-02-02T00:00:00.000Z'),
          updatedAt: new Date('2026-02-02T00:01:00.000Z'),
          entryCount: 2,
        },
      ],
    } as unknown as SessionStore;
    const h = harness([], {}, store);

    const list = h.send({type: 'list_sessions', limit: 3});
    await h.send({type: 'ping', timestamp: 7});
    await list;

    expect(h.frames()).toEqual(['session_list', 'pong 7']);
  });

  it('answers a store without listFor with an empty session_list, and a rejecting one with a single SERVER_ERROR and a socket that still answers', async () => {
    const unimplemented = harness([], {}, {} as unknown as SessionStore);
    await unimplemented.send({type: 'list_sessions'});

    const failing = harness([], {}, {
      listFor: () => Promise.reject(new Error('database offline')),
    } as unknown as SessionStore);
    await failing.send({type: 'list_sessions'});
    await failing.send({type: 'ping', timestamp: 8});

    expect({unimplemented: unimplemented.sent, failing: failing.frames()}).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failing: ['error SERVER_ERROR', 'pong 8'],
    });
  });

  it('answers the frame behind an answer whose send threw: a failed error delivery does not stall the queue', async () => {
    const sent: OutgoingMessage[] = [];
    // The socket that fails only while an error frame is written: the queue must outlive it.
    const ws = {
      send: (raw: string) => {
        const frame = JSON.parse(raw) as OutgoingMessage;
        if (frame.type === 'error') throw new Error('socket gone');
        sent.push(frame);
      },
    } as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler({processMessageStream: jest.fn()} as unknown as ChatOrchestrator);

    const failing = handle(ws, session, {type: 'nonsense'});
    const behind = handle(ws, session, {type: 'ping', timestamp: 7});

    await expect(failing).rejects.toThrow('socket gone');
    await expect(behind).resolves.toBeUndefined();

    expect(sent.map(frame => frame.type)).toEqual(['pong']);
  });
});

