159	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
160	function isUserMessageFrame(rawMessage: unknown): boolean {
161	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
162	}
