168	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
169	  try {
170	    await action();
171	  } catch (error) {
172	    const message = messageOf(error);
173	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
174	    log.error('message', 'handling error', {error: message, code});
175	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
176	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
177	      return;
178	    }
179	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
